ac:
set -u
cd apps/web
f=src/features/optimizer/use-strategy-inputs.ts
[ -f "$f" ] || { echo "훅 파일이 없다: $f"; exit 1; }
grep -q "useStrategy" "$f" || { echo "useStrategy 를 안 쓴다 — pine_source 를 어디서 얻나"; exit 1; }
grep -q "usePreviewParse" "$f" || { echo "usePreviewParse 를 안 쓴다 — inputs 를 어디서 얻나"; exit 1; }
grep -q "@/features/strategy/hooks" "$f" || { echo "양성 대조 실패: strategy 훅 모듈을 import 하지 않는다"; exit 1; }

set -u
cd apps/web
v=src/features/optimizer/components/optimizer-page-view.tsx
grep -q "useStrategyInputs" "$v" || { echo "page-view 가 useStrategyInputs 를 안 쓴다"; exit 1; }
grep -q "strategy_id" "$v" || { echo "page-view 가 선택된 백테스트에서 strategy_id 를 안 꺼낸다"; exit 1; }
n=0
for f in src/features/optimizer/components/grid-search-form.tsx src/features/optimizer/components/bayesian-search-form.tsx src/features/optimizer/components/genetic-search-form.tsx; do
  grep -q "inputs" "$f" && n=$((n+1))
done
[ "$n" = "3" ] || { echo "3폼 중 ${n}개만 inputs 를 통과시킨다"; exit 1; }
